<template>
  <ViewShell title="监测参数设置" tag="阈值与水位配置" :icon="SlidersOutlined">
    <section class="view-card manage-panel"><div class="manage-toolbar"><div><h2 class="view-card__title"><SlidersOutlined /> 水位与监测阈值</h2><p class="manage-subtitle">设置平台告警判断使用的上下限，修改后立即保存到数据库。</p></div><button v-if="canEdit" class="primary-btn" type="button" @click="openCreate">新增参数</button></div><div v-if="error" class="manage-error">{{ error }}</div><div class="param-grid"><article v-for="item in params" :key="item.paramId" class="param-card"><div class="param-card__head"><div><strong>{{ item.paramName || item.paramCode }}</strong><small>{{ item.paramCode }}</small></div><span>{{ item.paramType || '监测' }}</span></div><div class="param-values"><div><small>下限</small><b>{{ item.paramLowValue || '—' }}</b></div><div class="value-line"></div><div><small>上限</small><b>{{ item.paramHighValue || '—' }}</b></div></div><p>{{ item.remark || '未填写备注' }}</p><div class="param-card__actions"><button v-if="canEdit" type="button" @click="openEdit(item)">编辑</button><button v-if="canEdit" type="button" class="danger-link" @click="remove(item)">删除</button></div></article><div v-if="!loading && !params.length" class="manage-empty">还没有配置参数</div><div v-if="loading" class="manage-empty">正在读取参数…</div></div></section>
    <div v-if="editing" class="modal-backdrop" @click.self="editing = null"><form class="manage-modal" @submit.prevent="save"><div class="modal-head"><div><h2>{{ editing.paramId ? '编辑监测参数' : '新增监测参数' }}</h2><p>参数编码用于后续规则和告警关联。</p></div><button type="button" class="close-btn" @click="editing = null">×</button></div><div class="form-grid"><label>参数编码<input v-model.trim="editing.paramCode" required placeholder="例如 water_level" /></label><label>参数名称<input v-model.trim="editing.paramName" required /></label><label>下限值<input v-model.trim="editing.paramLowValue" /></label><label>上限值<input v-model.trim="editing.paramHighValue" /></label><label>参数类型<select v-model="editing.paramType"><option>水情</option><option>水质</option><option>闸门</option><option>系统</option></select></label><label class="span-2">备注<textarea v-model.trim="editing.remark" rows="3"></textarea></label></div><div class="modal-foot"><button type="button" class="plain-btn" @click="editing = null">取消</button><button class="primary-btn" type="submit">保存参数</button></div></form></div>
  </ViewShell>
</template>

<script setup>
import { onMounted, ref } from 'vue'
import { SlidersOutlined } from '@ant-design/icons-vue'
import ViewShell from './ViewShell.vue'
const accountLevel = Number(localStorage.getItem('level') ?? 1)
const canEdit = accountLevel === 0 || accountLevel >= 2
import { addParam, deleteParam, listParams, updateParam } from '../api/manageApi.js'
const params = ref([]); const loading = ref(true); const error = ref(''); const editing = ref(null)
const blank = () => ({ paramCode: '', paramName: '', paramLowValue: '', paramHighValue: '', paramType: '水情', remark: '' })
async function load() { loading.value = true; try { const result = await listParams(); params.value = result.data || [] } catch (e) { error.value = e.message } finally { loading.value = false } }
function openCreate() { editing.value = blank() }
function openEdit(item) { editing.value = { ...item } }
async function save() { try { if (editing.value.paramId) await updateParam(editing.value); else await addParam(editing.value); editing.value = null; await load() } catch (e) { error.value = e.message } }
async function remove(item) { if (!window.confirm(`确定删除“${item.paramName}”吗？`)) return; try { await deleteParam(item.paramId); await load() } catch (e) { error.value = e.message } }
onMounted(load)
</script>

<style scoped>
.manage-panel{min-height:100%}.manage-toolbar{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:18px}.manage-subtitle{margin:-8px 0 0;color:#7890a4;font-size:11px}.primary-btn,.plain-btn{height:34px;padding:0 14px;border:0;border-radius:8px;font-size:12px;cursor:pointer}.primary-btn{background:#1679d1;color:white}.plain-btn{border:1px solid #d8e5ee;background:#fff;color:#557188}.manage-error{padding:10px 12px;border-radius:8px;background:#fff2f1;color:#b64c4a;font-size:12px}.param-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.param-card{padding:16px;border:1px solid #e1ecf3;border-radius:12px;background:#fbfdfe}.param-card__head{display:flex;justify-content:space-between;gap:8px;align-items:flex-start}.param-card__head strong,.param-card__head small{display:block}.param-card__head strong{color:#294b66;font-size:14px}.param-card__head small{margin-top:3px;color:#9aaebb;font-size:10px}.param-card__head span{padding:4px 7px;border-radius:5px;background:#edf7fd;color:#3189b6;font-size:10px}.param-values{display:flex;align-items:center;gap:10px;margin:18px 0 13px}.param-values small,.param-values b{display:block}.param-values small{color:#96a8b5;font-size:10px}.param-values b{margin-top:2px;color:#1a6598;font-size:20px}.value-line{flex:1;height:1px;background:#dbe9f1}.param-card p{min-height:18px;margin:0;color:#8498a8;font-size:10px}.param-card__actions{display:flex;justify-content:flex-end;gap:11px;margin-top:14px;padding-top:11px;border-top:1px solid #edf2f5}.param-card__actions button{border:0;background:none;color:#247cc2;font-size:11px;cursor:pointer}.danger-link{color:#d06462!important}.manage-empty{grid-column:1/-1;text-align:center;color:#91a4b2;padding:28px}.modal-backdrop{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(9,35,58,.4)}.manage-modal{width:min(560px,100%);padding:22px;border-radius:15px;background:#fff;box-shadow:0 20px 60px rgba(13,53,82,.25)}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.modal-head h2{margin:0;color:#173955;font-size:18px}.modal-head p{margin:4px 0 0;color:#8298a9;font-size:11px}.close-btn{border:0;background:none;color:#8197a7;font-size:24px;cursor:pointer}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.form-grid label{display:flex;flex-direction:column;gap:5px;color:#617b90;font-size:11px}.form-grid input,.form-grid select,.form-grid textarea{border:1px solid #dce8f0;border-radius:8px;background:#fbfdfe;color:#284967;font:inherit;font-size:12px;outline:none}.form-grid input,.form-grid select{height:35px;padding:0 9px}.form-grid textarea{padding:8px;resize:vertical}.span-2{grid-column:span 2}.modal-foot{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}@media(max-width:900px){.param-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.manage-toolbar{flex-direction:column}.param-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.span-2{grid-column:auto}}
</style>
